// Pull the binary resume file + text form fields out of the multipart request.
// N8N stores uploaded files in $binary; text fields land in $json.body (N8N 1.x)
// or directly in $json (older versions) — we handle both.

const item = $input.first();
const bin  = item.binary || {};

// The file input field on the frontend is named 'resume'
const resumeBin = bin.resume || bin.data || bin.file;
if (!resumeBin) {
  throw new Error(
    'No resume binary found. Ensure the frontend sends the file in a field named "resume" ' +
    'and that the Webhook node has "Binary Data" enabled in its settings.'
  );
}

// Text fields: try body.* first (N8N 1.x), fallback to top-level json
const body = item.json?.body ?? item.json ?? {};

const parseJSON = (val, fallback) => {
  if (!val) return fallback;
  try { return JSON.parse(val); } catch (_) { return fallback; }
};

return [{
  json: {
    // base64-encoded PDF (N8N already base64-encodes binary fields)
    resumeBase64: resumeBin.data,
    mimeType:     resumeBin.mimeType  || 'application/pdf',
    fileName:     resumeBin.fileName  || 'resume.pdf',
    // Preferences from the form
    locations:  parseJSON(body.locations, []),
    roles:      parseJSON(body.roles, []),
    salaryMin:  parseInt(body.salaryMin ?? '0',   10),
    salaryMax:  parseInt(body.salaryMax ?? '200', 10)
  }
}];

// Merge the extracted resume text with the original user preferences.
// We reference the 'Encode Resume' node to retrieve location/role/salary data
// since the current node only receives the Firebase response ({ text, pages }).

const extractResult = $input.first().json;
const prefs         = $('Encode Resume').first().json;

if (!extractResult.text) {
  throw new Error(
    'Resume text extraction returned no text. Firebase response: ' +
    JSON.stringify(extractResult)
  );
}

return [{
  json: {
    resumeText: extractResult.text,
    pages:      extractResult.pages,
    locations:  prefs.locations,
    roles:      prefs.roles,
    salaryMin:  prefs.salaryMin,
    salaryMax:  prefs.salaryMax
  }
}];
